    temp = ''
    plus_minus = 1      # variable for managing + and -
    while counter < len(sequence):
        try:
            int(sequence[counter])
            temp += sequence[counter]
        except ValueError:
            total += int(temp)*plus_minus
            temp = ''
            if sequence[counter] == u'-':
                plus_minus = -1
            if sequence[counter] == u'+':
                plus_minus = 1
        counter += 1
    total += int(temp)*plus_minus
    return total

